use pansy_meteor_matched_filter::Filter;
use rustfft::num_complex::Complex32;

#[test]
fn rejects_invalid_inputs() {
    assert!(Filter::new(vec![3, 2], 132, 1, 256).is_err());
    assert!(Filter::new(vec![0], 132, 1, 128).is_err());
    let mut f = Filter::new(vec![0], 8, 1, 16).unwrap();
    assert!(f
        .process(
            &[Complex32::default(); 16],
            1,
            16,
            &[Complex32::default(); 8]
        )
        .is_err());
}

#[test]
#[ignore = "generated by compare_reference.py using recorded and synthetic voltages"]
fn python_reference() {
    let file = hdf5::File::open(std::env::var("MF_REFERENCE").unwrap()).unwrap();
    for name in file.member_names().unwrap() {
        let g = file.group(&name).unwrap();
        let re = g.dataset("rx_re").unwrap();
        let shape = re.shape();
        let rx: Vec<_> = re
            .read_raw::<f32>()
            .unwrap()
            .into_iter()
            .zip(g.dataset("rx_im").unwrap().read_raw::<f32>().unwrap())
            .map(|(r, i)| Complex32::new(r, i))
            .collect();
        let tx: Vec<_> = g
            .dataset("tx_re")
            .unwrap()
            .read_raw::<f32>()
            .unwrap()
            .into_iter()
            .zip(g.dataset("tx_im").unwrap().read_raw::<f32>().unwrap())
            .map(|(r, i)| Complex32::new(r, i))
            .collect();
        let dec = g.attr("decimation").unwrap().read_scalar::<u64>().unwrap() as usize;
        let gates = g
            .dataset("gates")
            .unwrap()
            .read_raw::<u64>()
            .unwrap()
            .into_iter()
            .map(|x| x as usize)
            .collect();
        let mut filter = Filter::new(gates, tx.len(), dec, 256).unwrap();
        let result = filter.process(&rx, shape[0], shape[1], &tx).unwrap();
        let expected = g.dataset("power").unwrap().read_raw::<f32>().unwrap();
        let scale = expected.iter().copied().fold(0.0_f32, f32::max);
        let error = expected
            .iter()
            .zip(&result.power)
            .map(|(a, b)| (a - b).abs())
            .fold(0.0_f32, f32::max)
            / scale;
        assert!(error < 3e-6, "{name}: relative power error {error}");
        let noise = g.attr("median").unwrap().read_scalar::<f32>().unwrap();
        assert!(
            (result.median_power / noise - 1.0).abs() < 3e-6,
            "{name}: median"
        );
        let peaks = result.peaks(2.0, 16, 4, 4).unwrap();
        let er = g.dataset("complex_re").unwrap().read_raw::<f32>().unwrap();
        let ei = g.dataset("complex_im").unwrap().read_raw::<f32>().unwrap();
        for p in &peaks {
            let ri = result
                .gates
                .iter()
                .position(|&x| x == p.range_sample)
                .unwrap();
            for (ch, z) in p.receiver_amplitudes.iter().enumerate() {
                let idx = ch * expected.len() + ri * 256 + p.doppler_bin;
                assert!((*z - Complex32::new(er[idx], ei[idx])).norm() < 3e-5 * scale.sqrt());
            }
        }
        if name == "two_targets_d1" {
            for (gate, bin) in [(20, 151), (180, 91)] {
                assert!(
                    peaks
                        .iter()
                        .any(|p| p.range_sample == gate && p.doppler_bin == bin),
                    "missing target {gate}/{bin}: {peaks:?}"
                );
            }
        }
        let now = std::time::Instant::now();
        for _ in 0..20 {
            std::hint::black_box(filter.process(&rx, shape[0], shape[1], &tx).unwrap());
        }
        println!(
            "{name}: max power error={error:.2e}, {} peaks, {:.3} ms/pulse",
            peaks.len(),
            now.elapsed().as_secs_f64() * 1000.0 / 20.0
        );
    }
}
